package leveling

import (
	"path/filepath"
	"testing"
)

// A cat casts no Arcane or Nature spell in its rotation, so Nature's Focus ("your Arcane and
// Nature spells ... not lose casting time") and Subtlety ("threat generated by your Nature and
// Arcane spells") do nothing for it. The leveling build spent eight points there while Heart
// of the Wild sat at 3/5 (sim-accuracy round 15). No band of the cat ladder may hold either.
func TestCatLevelingBuildSpendsNothingOnCasterOnlyTalents(t *testing.T) {
	repoRoot := filepath.Join("..", "..")
	active, err := ReadActiveBuild(repoRoot)
	if err != nil {
		t.Fatal(err)
	}
	trees, err := LoadTalentTrees(repoRoot, active, "druid")
	if err != nil {
		t.Fatal(err)
	}
	_, digits, err := GuideBuildTalents(repoRoot, "druid", "feral")
	if err != nil {
		t.Fatal(err)
	}
	targets := GuideTalentTargets(trees, digits)
	const feralTree, restorationTree = 1, 2

	for _, name := range []string{"Nature's Focus", "Subtlety"} {
		found := false
		for _, node := range trees[restorationTree].Talents {
			if node.Name != name {
				continue
			}
			found = true
			if got := targets[node.ID]; got != 0 {
				t.Errorf("the cat leveling build spends %d points on %s, want 0", got, name)
			}
		}
		if !found {
			t.Fatalf("no %s in the Restoration tree", name)
		}
	}

	ranks, err := TalentRanksFromString(trees, LadderTalentString(trees, targets, feralTree, 60, ForSpec("druid-feral")))
	if err != nil {
		t.Fatal(err)
	}
	for _, node := range trees[restorationTree].Talents {
		if node.Name == "Heart of the Wild" && ranks[node.ID] != node.MaxRank {
			t.Errorf("the cat's level 60 build has Heart of the Wild %d, want %d", ranks[node.ID], node.MaxRank)
		}
	}
}
